#!/bin/bash
# Prints the three most frequent IP addresses in access.log, one per line,
# most frequent first; ties broken by first appearance in the log.
set -eu

awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first)) {   # record first-appearance order
        first[ip] = ++order
        ips[order] = ip
    }
}
END {
    n = order
    # selection sort: highest count first, ties by earliest first appearance
    for (i = 1; i < n; i++) {
        best = i
        for (j = i + 1; j <= n; j++) {
            if (count[ips[j]] > count[ips[best]] ||
                (count[ips[j]] == count[ips[best]] && first[ips[j]] < first[ips[best]]))
                best = j
        }
        if (best != i) { t = ips[i]; ips[i] = ips[best]; ips[best] = t }
        if (i == 3) break
        if (i == 3) break
    }
    limit = (n < 3) ? n : 3
    for (i = 1; i <= limit; i++) print ips[i]
}
' access.log

#!/bin/bash
# Prints the three most frequent IP addresses in access.log, one per line,
# most frequent first; ties broken by first appearance in the log.
set -eu

awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first)) {   # record first-appearance order
        first[ip] = ++order
        ips[order] = ip
    }
}
END {
    n = order
    limit = (n < 3) ? n : 3
    # select the top `limit` entries: highest count first,
    # ties by earliest first appearance
    for (i = 1; i <= limit; i++) {
        best = -1
        for (j = 1; j <= n; j++) {
            if (chosen[j]) continue
            if (best == -1 ||
                count[ips[j]] > count[ips[best]] ||
                (count[ips[j]] == count[ips[best]] && first[ips[j]] < first[ips[best]]))
                best = j
        }
        chosen[best] = 1
        print ips[best]
    }
}
' access.log
